1	// What the desktop shell adds to a page, when there is one (docs/plan.md, step 4).
2	//
3	// The shell brings `window.preludeDesktop` on Prelude's own origin. Controls
4	// only the shell can drive are marked `data-desktop-only` and shown only when
5	// it is here; links it can do better are taken over - Pop out gets a real
6	// window, Open in browser the system's browser, Capture's What's in view the
7	// frame exactly as it is on screen. In a browser none of this runs, and
8	// nothing is lost: the links work as links, and the form as a form.
9	//
10	// This is the device's half: it relays between the page and the shell, and
11	// decides nothing. It is a script because it is genuinely imperative - a
12	// native dialog, a native window, the window's own pixels - which no binding
13	// or action expresses.
14	
15	const desktop = window.preludeDesktop ?? null;
16	
17	if (desktop) {
18	  // The page's root: .prelude in the app's layout, the document in the shell's.
19	  (document.querySelector('.prelude') ?? document.documentElement).setAttribute('data-desktop', '');
20	
21	  const taken = desktop.capture
22	    ? '[data-pick-folder], a[data-pop-out], a[target="_blank"], [data-capture-shown]'
23	    : '[data-pick-folder], a[data-pop-out], a[target="_blank"]';
24	  document.addEventListener('click', event => {
25	    const control = event.target.closest?.(taken);
26	    if (!control || event.defaultPrevented || event.button !== 0) return;
27	    event.preventDefault();
28	    event.stopPropagation();
29	    run(control).catch(error => console.error('Prelude desktop:', error));
30	  }, true);
31	}
