265	/// The system browser opens this server's pages and its preview origin's, over http(s).
266	fn may_open_in_browser(url: &Url, server: &Url) -> bool {
267	    matches!(url.scheme(), "http" | "https")
268	        && (same_origin(url, server) || (url.host_str() == Some(PREVIEW_HOST) && url.port_or_known_default() == server.port_or_known_default()))
269	}
