271	/// A window label from the page's window name: letters, digits and dashes only.
272	fn label_for(name: &str) -> String {
273	    let clean: String = name.chars().map(|c| if c.is_ascii_alphanumeric() || c == '-' { c } else { '-' }).take(80).collect();
274	    format!("design-{clean}")
275	}
