279	/// Async, like every command that waits on a dialog or makes a window: on
280	/// Windows, doing either from a synchronous command can deadlock the event loop.
281	#[tauri::command]
282	async fn pick_folder(window: WebviewWindow) -> Option<String> {
283	    window
284	        .dialog()
285	        .file()
286	        .set_title("Open a folder in Prelude")
287	        .set_parent(&window)
288	        .blocking_pick_folder()
289	        .and_then(|path| path.into_path().ok())
290	        .map(|path: PathBuf| path.display().to_string())
291	}
